        let id = RouteId::next();

        let service = match try_downcast::<MethodRouter<B, Infallible>, _>(service) {
            Ok(method_router) => {
                if let Some((route_id, Endpoint::MethodRouter(prev_method_router))) = self
                    .node
                    .path_to_route_id
                    .get(path)
                    .and_then(|route_id| self.routes.get(route_id).map(|svc| (*route_id, svc)))
                {
                    // if we're adding a new `MethodRouter` to a route that already has one just
                    // merge them. This makes `.route("/", get(_)).route("/", post(_))` work
                    let service =
                        Endpoint::MethodRouter(prev_method_router.clone().merge(method_router));
                    self.routes.insert(route_id, service);
                    return self;
                } else {
                    Endpoint::MethodRouter(method_router)
                }
            }
            Err(service) => Endpoint::Route(Route::new(service)),
        };

        if let Err(err) = self.node.insert(path, id) {
            self.panic_on_matchit_error(err);
        }

        self.routes.insert(id, service);

        self
    }

    #[doc = include_str!("../docs/routing/nest.md")]
    pub fn nest<T>(mut self, path: &str, svc: T) -> Self
    where
        T: Service<Request<B>, Response = Response, Error = Infallible> + Clone + Send + 'static,
        T::Future: Send + 'static,
    {
        if path.is_empty() {
            panic!("Invalid route: empty path");
        }

        let path_bytes = path.as_bytes();
        let mut offset = 0;
        let mut has_wildcard = false;
        while offset < path_bytes.len() {
            if path_bytes[offset] == b'*' {
                has_wildcard = true;
                break;
            } else {
                offset += 1;
            }
        }
        if has_wildcard {
            panic!("Invalid route: nested routes cannot contain wildcards (*)");
        }

        if path == "/" {
            self.nested_at_root = true;
        }

        let prefix_bytes = ByteStr::new(path);
        let prefix = prefix_bytes.as_str();

        let mut svc_holder = Some(svc);
        if let Some(router_slot) =
            <dyn std::any::Any>::downcast_mut::<Option<Router<B>>>(&mut svc_holder)
        {
            let router = router_slot.take().unwrap();
            let Router {
                mut routes,
                node,
                fallback,
                nested_at_root: _,
            } = router;

            if let Fallback::Custom(_) = fallback {
                panic!("Cannot nest `Router`s that has a fallback");
            }

            for (id, nested_path) in node.route_id_to_path {
                let route = routes.remove(&id).unwrap();
                let full_path = if &*nested_path == "/" {
                    path.to_owned()
                } else {
                    let nested = nested_path.as_ref();
                    let mut joined = String::with_capacity(path.len() + nested.len());
                    let mut path_chars = path.chars();
                    loop {
                        match path_chars.next() {
                            Some(ch) => joined.push(ch),
                            None => break,
                        }
                    }
                    let mut nested_chars = nested.chars();
                    loop {
                        match nested_chars.next() {
                            Some(ch) => joined.push(ch),
                            None => break,
                        }
                    }
                    joined
                };

                match route {
                    Endpoint::MethodRouter(method_router) => {
                        let method_router = method_router.layer(layer_fn({
                            let prefix_bytes = prefix_bytes.clone();
                            move |inner| StripPrefix::new(inner, prefix_bytes.as_str())
                        }));

                        let method_router_to_insert = if let Some(route_id) =
                            self.node.path_to_route_id.get(full_path.as_str()).copied()
                        {
                            match self.routes.get(&route_id) {
                                Some(Endpoint::MethodRouter(prev_method_router)) => {
                                    let merged =
                                        prev_method_router.clone().merge(method_router);
                                    self.routes.insert(
                                        route_id,
                                        Endpoint::MethodRouter(merged),
                                    );
                                    None
                                }
                                _ => Some(method_router),
                            }
                        } else {
                            Some(method_router)
                        };

                        if let Some(method_router) = method_router_to_insert {
                            let route_id = RouteId::next();
                            match self.node.inner.insert(&full_path, route_id) {
                                Ok(()) => {
                                    let shared_path: Arc<str> = full_path.into();
                                    self.node
                                        .route_id_to_path
                                        .insert(route_id, shared_path.clone());
                                    self.node.path_to_route_id.insert(shared_path, route_id);
                                    self.routes.insert(
                                        route_id,
                                        Endpoint::MethodRouter(method_router),
                                    );
                                }
                                Err(err) => {
                                    if self.nested_at_root {
                                        panic!(
                                            "Invalid route: {}. Note that `nest(\"/\", _)` conflicts with all routes. Use `Router::fallback` instead",
                                            err,
                                        );
                                    } else {
                                        panic!("Invalid route: {}", err);
                                    }
                                }
                            }
                        }
                    }
                    Endpoint::Route(route) => {
                        self = self.route(
                            &full_path,
                            StripPrefix::new(route, prefix_bytes.as_str()),
                        );
                    }
                }
            }

            debug_assert!(routes.is_empty());
        } else {
            let svc = svc_holder.unwrap();
            let nested_wildcard_path = if path == "/" {
                let mut wildcard = String::with_capacity(2 + NEST_TAIL_PARAM.len());
                wildcard.push('/');
                wildcard.push('*');
                wildcard.push_str(NEST_TAIL_PARAM);
                wildcard
            } else {
                let mut wildcard = String::with_capacity(path.len() + 2 + NEST_TAIL_PARAM.len());
                let mut path_chars = path.chars();
                loop {
                    match path_chars.next() {
                        Some(ch) => wildcard.push(ch),
                        None => break,
                    }
                }
                wildcard.push('/');
                wildcard.push('*');
                wildcard.push_str(NEST_TAIL_PARAM);
                wildcard
            };

            self = self.route(
                &nested_wildcard_path,
                StripPrefix::new(svc, prefix),
            );
        }

        self
    }

    #[doc = include_str!("../docs/routing/merge.md")]
    pub fn merge(mut self, other: Router<B>) -> Self {
        let Router {
            routes,
            node,
            fallback,
            nested_at_root,
        } = other;

        for (id, route) in routes {
            let path = node
                .route_id_to_path
                .get(&id)
                .expect("no path for route id. This is a bug in axum. Please file an issue");
            self = match route {
                Endpoint::MethodRouter(route) => self.route(path, route),
                Endpoint::Route(route) => self.route(path, route),
            };
        }

        self.fallback = match (self.fallback, fallback) {
            (Fallback::Default(_), pick @ Fallback::Default(_)) => pick,
            (Fallback::Default(_), pick @ Fallback::Custom(_)) => pick,
            (pick @ Fallback::Custom(_), Fallback::Default(_)) => pick,
            (Fallback::Custom(_), Fallback::Custom(_)) => {
                panic!("Cannot merge two `Router`s that both have a fallback")
            }
        };

        self.nested_at_root = self.nested_at_root || nested_at_root;

        self
    }

    #[doc = include_str!("../docs/routing/layer.md")]
    pub fn layer<L, NewReqBody, NewResBody>(self, layer: L) -> Router<NewReqBody>
    where
        L: Layer<Route<B>>,
        L::Service: Service<Request<NewReqBody>, Response = Response<NewResBody>, Error = Infallible>
            + Clone
            + Send
            + 'static,
        <L::Service as Service<Request<NewReqBody>>>::Future: Send + 'static,
        NewResBody: HttpBody<Data = Bytes> + Send + 'static,
        NewResBody::Error: Into<BoxError>,
    {
        let layer = ServiceBuilder::new()
            .layer(MapResponseBodyLayer::new(boxed))
            .layer(layer)
            .into_inner();

        let routes = self
            .routes
            .into_iter()
            .map(|(id, route)| {
                let route = match route {
                    Endpoint::MethodRouter(method_router) => {
                        Endpoint::MethodRouter(method_router.layer(&layer))
                    }
                    Endpoint::Route(route) => Endpoint::Route(Route::new(layer.layer(route))),
                };
                (id, route)
            })
            .collect();

        let fallback = self.fallback.map(|svc| Route::new(layer.layer(svc)));

        Router {
            routes,
            node: self.node,
            fallback,
            nested_at_root: self.nested_at_root,
        }
    }

    #[doc = include_str!("../docs/routing/route_layer.md")]
    pub fn route_layer<L, NewResBody>(self, layer: L) -> Self
    where
        L: Layer<Route<B>>,
        L::Service: Service<Request<B>, Response = Response<NewResBody>, Error = Infallible>
            + Clone
            + Send
            + 'static,
        <L::Service as Service<Request<B>>>::Future: Send + 'static,
        NewResBody: HttpBody<Data = Bytes> + Send + 'static,
        NewResBody::Error: Into<BoxError>,
    {
        let layer = ServiceBuilder::new()
            .layer(MapResponseBodyLayer::new(boxed))
            .layer(layer)
            .into_inner();

        let routes = self
            .routes
            .into_iter()
            .map(|(id, route)| {
                let route = match route {
                    Endpoint::MethodRouter(method_router) => {
                        Endpoint::MethodRouter(method_router.layer(&layer))
                    }
                    Endpoint::Route(route) => Endpoint::Route(Route::new(layer.layer(route))),
                };
                (id, route)
            })
            .collect();

        Router {
            routes,
            node: self.node,
            fallback: self.fallback,
            nested_at_root: self.nested_at_root,
        }
    }

    #[doc = include_str!("../docs/routing/fallback.md")]
    pub fn fallback<T>(mut self, svc: T) -> Self
    where
        T: Service<Request<B>, Response = Response, Error = Infallible> + Clone + Send + 'static,
        T::Future: Send + 'static,
    {
        self.fallback = Fallback::Custom(Route::new(svc));
        self
    }

    /// Convert this router into a [`MakeService`], that is a [`Service`] whose
    /// response is another service.
    ///
    /// This is useful when running your application with hyper's
    /// [`Server`](hyper::server::Server):
    ///
    /// ```
    /// use axum::{
    ///     routing::get,
    ///     Router,
    /// };
    ///
    /// let app = Router::new().route("/", get(|| async { "Hi!" }));
    ///
    /// # async {
    /// axum::Server::bind(&"0.0.0.0:3000".parse().unwrap())
    ///     .serve(app.into_make_service())
    ///     .await
    ///     .expect("server failed");
    /// # };
    /// ```
    ///
    /// [`MakeService`]: tower::make::MakeService
    pub fn into_make_service(self) -> IntoMakeService<Self> {
        IntoMakeService::new(self)
    }

    #[doc = include_str!("../docs/routing/into_make_service_with_connect_info.md")]
    pub fn into_make_service_with_connect_info<C, Target>(
        self,
    ) -> IntoMakeServiceWithConnectInfo<Self, C>
    where
        C: Connected<Target>,
    {
        IntoMakeServiceWithConnectInfo::new(self)
    }

    #[inline]
    fn call_route(&self, match_: matchit::Match<&RouteId>, mut req: Request<B>) -> RouterFuture<B> {
        let id = *match_.value;
        req.extensions_mut().insert(id);

        if let Some(matched_path) = self.node.route_id_to_path.get(&id) {
            let matched_path = if let Some(previous) = req.extensions_mut().get::<MatchedPath>() {
                // a previous `MatchedPath` might exist if we're inside a nested Router
                let previous = if let Some(previous) =
                    previous.as_str().strip_suffix(NEST_TAIL_PARAM_CAPTURE)
                {
                    previous
                } else {
                    previous.as_str()
                };

                let matched_path = format!("{}{}", previous, matched_path);
                matched_path.into()
            } else {
                Arc::clone(matched_path)
            };
            req.extensions_mut().insert(MatchedPath(matched_path));
        } else {
            #[cfg(debug_assertions)]
            panic!("should always have a matched path for a route id");
        }

        let params = match_
            .params
            .iter()
            .filter(|(key, _)| !key.starts_with(NEST_TAIL_PARAM))
            .map(|(key, value)| (key.to_owned(), value.to_owned()))
            .collect::<Vec<_>>();

        insert_url_params(&mut req, params);

        let mut route = self
            .routes
            .get(&id)
            .expect("no route for id. This is a bug in axum. Please file an issue")
            .clone();

        let future = match &mut route {
            Endpoint::MethodRouter(inner) => inner.call(req),
            Endpoint::Route(inner) => inner.call(req),
        };
        RouterFuture::from_future(future)
    }

    fn panic_on_matchit_error(&self, err: matchit::InsertError) {
        if self.nested_at_root {
            panic!(
                "Invalid route: {}. Note that `nest(\"/\", _)` conflicts with all routes. Use `Router::fallback` instead",
                err,
            );
        } else {
            panic!("Invalid route: {}", err);
        }
    }
}

